{
  "version": 1,
  "categories": [
    {
      "kind": "structural",
      "entries": [
        {
          "kind": "structural",
          "name": "All",
          "origin": {
            "kind": "structural",
            "construct": "All"
          },
          "syntax": [
            "<All><Spawn>…</Spawn><Spawn>…</Spawn></All>"
          ],
          "description": "Run tasks in parallel. `<All><Spawn>first</Spawn><Spawn>second</Spawn></All>` expands every task at the same time, waits for them all to succeed, and preserves their Markdown order. Write at least two `<Spawn>` children directly inside it; if one fails, unfinished tasks are cancelled and `<All>` produces no output.",
          "context": "The `<Spawn>` children this runs at the same time."
        },
        {
          "kind": "structural",
          "name": "Answer",
          "origin": {
            "kind": "structural",
            "construct": "Answer"
          },
          "syntax": [
            "<Answer template=\"text\" value={value} />",
            "<Answer value={value}>…</Answer>"
          ],
          "description": "Supply one answer inside `<Answers>`. `<Answer template=\"Approve {?what}?\" value={{ ok: true }} />` answers any elicitation its template matches — `{?name}` matches any text. The first matching `<Answer>` wins.",
          "context": "A multiline template, in place of the single-line `template` prop."
        },
        {
          "kind": "structural",
          "name": "Answers",
          "origin": {
            "kind": "structural",
            "construct": "Answers"
          },
          "syntax": [
            "<Answers>…</Answers>"
          ],
          "description": "Answer any `<Elicit>` in its content without asking a person. `<Answers>…</Answers>` replies from the `<Answer>` matchers declared inside it, reaching elicitations from nested components too. `delegate` passes an unmatched one outward instead of failing.",
          "context": "`<Answer>` matchers, and the body they answer for."
        },
        {
          "kind": "structural",
          "name": "Break",
          "origin": {
            "kind": "structural",
            "construct": "Break"
          },
          "syntax": [
            "<Break />"
          ],
          "description": "Exit the nearest enclosing `<Loop>`. `<Break />` stops the current iteration where it is; nothing after it in that iteration runs."
        },
        {
          "kind": "structural",
          "name": "Case",
          "origin": {
            "kind": "structural",
            "construct": "Case"
          },
          "syntax": [
            "<Case value={value}>…</Case>",
            "<Case default>…</Case>"
          ],
          "description": "Define one branch of a `<Switch>`. `<Case value=\"ready\">…</Case>` matches with `===`; `<Case default>…</Case>` is the final fallback.",
          "context": "Markdown expanded when this case is selected."
        },
        {
          "kind": "structural",
          "name": "Catch",
          "origin": {
            "kind": "structural",
            "construct": "Catch"
          },
          "syntax": [
            "<Catch as=\"error\">…</Catch>",
            "<Catch>…</Catch>"
          ],
          "description": "Handle a failure in the preceding Try body. `<Catch as=\"error\">{error.message}</Catch>` runs after clean release; its bindings stay local. Cancellation skips this branch.",
          "as": "Optional. Binds the ordinary Error by reference in this branch.",
          "context": "Recovery content."
        },
        {
          "kind": "structural",
          "name": "Content",
          "origin": {
            "kind": "structural",
            "construct": "Content"
          },
          "syntax": [
            "<Content />",
            "<Content slot=\"name\" />"
          ],
          "description": "Render what the caller wrote inside this component. `<Content />` renders all of it; `<Content slot=\"footer\" />` renders just the part the caller marked `slot=\"footer\"`."
        },
        {
          "kind": "structural",
          "name": "Each",
          "origin": {
            "kind": "structural",
            "construct": "Each"
          },
          "syntax": [
            "<Each in={list} let=\"item\">…</Each>"
          ],
          "description": "Repeat content for each item in an array. `<Each in={list} let=\"item\">…</Each>` binds each one to `item` inside.",
          "as": "Optional. Captures the whole rendered loop instead of emitting it.",
          "context": "Markdown rendered once per element."
        },
        {
          "kind": "structural",
          "name": "Else",
          "origin": {
            "kind": "structural",
            "construct": "Else"
          },
          "syntax": [
            "<Else>…</Else>"
          ],
          "description": "The branch `<If>` takes when its condition is false. `<Else>…</Else>` is written directly inside an `<If>`, and is an error anywhere else.",
          "context": "The branch taken when the enclosing condition does not hold."
        },
        {
          "kind": "structural",
          "name": "Finally",
          "origin": {
            "kind": "structural",
            "construct": "Finally"
          },
          "syntax": [
            "<Finally>…</Finally>"
          ],
          "description": "Finish a Try after its attempted body and recovery. `<Finally>Cleanup.</Finally>` also runs and joins on terminal Stop. Resumable Exit leaves an unentered branch pending; failed release and infrastructure failure prevent new entry.",
          "context": "Completion content using the surrounding bindings."
        },
        {
          "kind": "structural",
          "name": "If",
          "origin": {
            "kind": "structural",
            "construct": "If"
          },
          "syntax": [
            "<If condition={condition}>…</If>"
          ],
          "description": "Expand content only when a condition is true. `<If condition={ready}>…</If>` expands its content, or the `<Else>` branch instead. The branch not taken never runs.",
          "context": "The branch taken when the condition holds, up to an `<Else>`."
        },
        {
          "kind": "structural",
          "name": "Let",
          "origin": {
            "kind": "structural",
            "construct": "Let"
          },
          "syntax": [
            "<Let as=\"name\">…</Let>",
            "<Let as=\"name\" value={value} />"
          ],
          "description": "Bind a name for the rest of the region. `<Let as=\"plan\">…</Let>` binds what its content rendered; `<Let as=\"plan\" value={result} />` binds the value. `select` narrows the rendered content to one CSS selection.",
          "as": "Required. The binding name the value is available under.",
          "context": "Markdown whose rendered text becomes the binding, in the paired form."
        },
        {
          "kind": "structural",
          "name": "Loop",
          "origin": {
            "kind": "structural",
            "construct": "Loop"
          },
          "syntax": [
            "<Loop max={count}>…</Loop>"
          ],
          "description": "Repeat content up to `max` times. `<Loop max={5}>…</Loop>` expands its content again and again until a `<Break>` inside it, or until `max` is reached. `max` is required.",
          "context": "Markdown expanded once per iteration."
        },
        {
          "kind": "structural",
          "name": "Output",
          "origin": {
            "kind": "structural",
            "construct": "Output"
          },
          "syntax": [
            "<Output>…</Output>"
          ],
          "description": "Restrict what a document or component renders. `<Output>…</Output>` becomes its entire output; anything outside the region is not rendered.",
          "context": "The rendered output the run presents."
        },
        {
          "kind": "structural",
          "name": "PrintErrors",
          "origin": {
            "kind": "structural",
            "construct": "PrintErrors"
          },
          "syntax": [
            "<PrintErrors>…</PrintErrors>"
          ],
          "description": "Convert thrown errors into output without failing. `<PrintErrors>…</PrintErrors>` renders any failure inside it as part of the output.",
          "context": "The region whose failures are printed rather than raised."
        },
        {
          "kind": "structural",
          "name": "Return",
          "origin": {
            "kind": "structural",
            "construct": "Return"
          },
          "syntax": [
            "<Return value={value} />"
          ],
          "description": "Return a value instead of rendered markdown. `<Return value={result} />` hands the value to the caller, checked against the component's declared `returns` schema."
        },
        {
          "kind": "structural",
          "name": "Spawn",
          "origin": {
            "kind": "structural",
            "construct": "Spawn"
          },
          "syntax": [
            "<Spawn>…</Spawn>"
          ],
          "description": "Run a task in parallel inside of `<All>`. Write `<Spawn>…</Spawn>` directly inside `<All>`; bindings made in its content stay with that task, and `<Return>` or `<Break>` cannot affect work outside it.",
          "context": "Markdown expanded in its own child, beside its siblings."
        },
        {
          "kind": "structural",
          "name": "Switch",
          "origin": {
            "kind": "structural",
            "construct": "Switch"
          },
          "syntax": [
            "<Switch value={value}>…</Switch>"
          ],
          "description": "Choose one branch by comparing a value with `===`. `<Switch value={status}><Case value=\"ready\">…</Case><Case default>…</Case></Switch>` expands the first matching case, or the final default when none matches.",
          "context": "Direct `<Case>` branches considered in source order."
        },
        {
          "kind": "structural",
          "name": "Try",
          "origin": {
            "kind": "structural",
            "construct": "Try"
          },
          "syntax": [
            "<Try>…<Catch>…</Catch><Finally>…</Finally></Try>"
          ],
          "description": "Recover an ordinary failure after its resources close. `<Try>…<Catch>fallback</Catch></Try>` keeps the rendered prefix and stops the attempted body at failure. Write Catch, Finally, or both. Failed release and infrastructure failures end execution.",
          "context": "Attempted content followed by direct Catch and Finally branches."
        }
      ]
